arguments.new_string:
public class Previewer extends AbstractFlashcardViewer {
    /** Bundle key for the index of the card currently being previewed */
    private static final String KEY_INDEX = "index";
    /** Bundle key for whether the answer side of the current card is being shown */
    private static final String KEY_SHOWING_ANSWER = "showingAnswer";

    private long[] mCardList;
    private int mIndex;
    private boolean mShowingAnswer;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        Timber.d("onCreate()");
        super.onCreate(savedInstanceState);

        mCardList = getIntent().getLongArrayExtra("cardList");
        mIndex = getIntent().getIntExtra(KEY_INDEX, -1);

        // Restore the position within the preview if the activity was recreated
        // (e.g. on a screen rotation), otherwise we'd jump back to the first card.
        if (savedInstanceState != null) {
            mIndex = savedInstanceState.getInt(KEY_INDEX, mIndex);
            mShowingAnswer = savedInstanceState.getBoolean(KEY_SHOWING_ANSWER, false);
        }

        if (mCardList == null || mCardList.length == 0 || mIndex < 0 || mIndex > mCardList.length - 1) {
            Timber.e("Previewer started with empty card list or invalid index");
            finishWithoutAnimation();
            return;
        }
        showBackIcon();
        // Ensure navigation drawer can't be opened. Various actions in the drawer cause crashes.
        disableDrawerSwipe();
        startLoadingCollection();
    }


    @Override
    public void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        outState.putInt(KEY_INDEX, mIndex);
        outState.putBoolean(KEY_SHOWING_ANSWER, mShowingAnswer);
    }


    @Override
    protected void onCollectionLoaded(Collection col) {
        super.onCollectionLoaded(col);
        mCurrentCard = col.getCard(mCardList[mIndex]);
        // displayCardQuestion() resets the state needed to render the answer, so it must always
        // run first, even when we're restoring a previewer which was showing the answer side.
        boolean restoreAnswer = mShowingAnswer;
        displayCardQuestion();
        if (restoreAnswer) {
            displayCardAnswer();
        }
        showBackIcon();
    }

