106	    private void selectDeckFromExtra() {
107	        Bundle extras = getIntent().getExtras();
108	        long did = Long.MIN_VALUE;
109	        if (extras != null) {
110	            did = extras.getLong("deckId", Long.MIN_VALUE);
111	        }
112	
113	        if(did == Long.MIN_VALUE) {
114	            // deckId is not set, load default
115	            return;
116	        }
117	
118	        Timber.d("selectDeckFromExtra() with deckId = %d", did);
119	
120	        // Clear the undo history when selecting a new deck
121	        if (getCol().getDecks().selected() != did) {
122	            getCol().clearUndo();
123	        }
124	        // Select the deck
125	        getCol().getDecks().select(did);
126	        // Reset the schedule so that we get the counts for the currently selected deck
127	        getCol().getSched().reset();
128	    }
