470	        char keyPressed = (char) event.getUnicodeChar();
471	        if (mAnswerField != null && !mAnswerField.isFocused()) {
472		        if (sDisplayAnswer) {
473		            if (keyPressed == '1' || keyCode == KeyEvent.KEYCODE_BUTTON_Y) {
474		                answerCard(EASE_1);
475		                return true;
476		            }
477		            if (keyPressed == '2' || keyCode == KeyEvent.KEYCODE_BUTTON_X) {
478		                answerCard(EASE_2);
479		                return true;
480		            }
481		            if (keyPressed == '3' || keyCode == KeyEvent.KEYCODE_BUTTON_B) {
482		                answerCard(EASE_3);
483		                return true;
484		            }
485		            if (keyPressed == '4' || keyCode == KeyEvent.KEYCODE_BUTTON_A) {
486		                answerCard(EASE_4);
487		                return true;
488		            }
489		            if (keyCode == KeyEvent.KEYCODE_SPACE || keyCode == KeyEvent.KEYCODE_ENTER || keyCode == KeyEvent.KEYCODE_NUMPAD_ENTER) {
490		                answerCard(getDefaultEase());
491		                return true;
492		            }
493		        }
494	                else {
495	                    if (keyCode == KeyEvent.KEYCODE_BUTTON_Y || keyCode == KeyEvent.KEYCODE_BUTTON_X
496	                            || keyCode == KeyEvent.KEYCODE_BUTTON_B || keyCode == KeyEvent.KEYCODE_BUTTON_A) {
497	                        displayCardAnswer();
498	                        return true;
499	                    }
500	                }
