664	    /**
665	     * Whether or not dismiss note is available for current card and specified DismissType
666	     * @param type Currently only SUSPEND_NOTE and BURY_NOTE supported
667	     * @return true if there is another card of same note that could be dismissed
668	     */
669	    private boolean dismissNoteAvailable(DismissType type) {
670	        if (mCurrentCard == null || mCurrentCard.note() == null || mCurrentCard.note().cards().size() < 2) {
671	            return false;
672	        }
673	        List<Card> cards = mCurrentCard.note().cards();
674	        for(Card card : cards) {
675	            if (card.getId() == mCurrentCard.getId()) continue;
676	            int queue = card.getQueue();
677	            if(type == DismissType.SUSPEND_NOTE && queue != Card.QUEUE_SUSP) {
678	                return true;
679	            } else if (type == DismissType.BURY_NOTE &&
680	                    queue != Card.QUEUE_SUSP && queue != Card.QUEUE_USER_BRD && queue != Card.QUEUE_SCHED_BRD) {
681	                return true;
682	            }
683	        }
684	        return false;
685	    }
